// counterWidth is how many cells a tree node reserves for its count before
// the icon that follows it.
//
// statusBranches and certBranches stack three or four of these nodes —
// up/down/error, valid/to renew/expired/error — and each one ends its own
// line with an icon. Left-aligned, a single-digit count and a double-digit
// one push their icon by a different number of cells, and the run of icons
// that is supposed to read as one column reads as a staircase instead.
// Right-aligning the count is what keeps them on it.
const counterWidth = 2

// padCounter right-aligns a rendered count to counterWidth. The padding
// carries the background itself (Rule 115) — an unpainted pad would let the
// terminal's own background show through to the left of the digit.
func padCounter(s string) string {
	if n := counterWidth - lipgloss.Width(s); n > 0 {
		return theme.Bg(strings.Repeat(" ", n)) + s
	}
	return s
}

// alertCount renders one non-nominal state's tally. The glyph is the
// state's own — a cross for DOWN, an alert for ERROR, an hourglass for a
// coming renewal, :status's vocabulary — including at zero: a check mark on
// the "down" line said "everything is fine" right where one is looking for
// how many are down, and it's the line's state an icon names, not its
// count.
//
// It's the color that carries the count: dimmed at zero, because a red
// cross on "0 down" teaches the reader the color instead of alerting them.
// The icon stays to the right of the number, as everywhere else.
//
// The number and the icon share **the same** style — the caller's, not a
// fixed red: a certificate `to renew` is a warning (orange), not a finding
// (severityCount's red), and a number colored one way next to an icon
// colored another says the same fact twice in two different colors.
//
// The count is right-aligned to counterWidth (padCounter) so that this
// icon lines up with the ones on the sibling nodes above and below it.
func alertCount(n int, glyph string, style lipgloss.Style) string {
	if n == 0 {
		return padCounter(countValue(0)) + theme.Bg("  ") + theme.DimStyle.Render(glyph)
	}
	return padCounter(style.Render(fmt.Sprintf("%d", n))) + theme.Bg("  ") + style.Render(glyph)
}

